-- Index for efficient category lookups (if not already exists)
CREATE INDEX IF NOT EXISTS idx_tool_classification_categories
  ON tool_classification_cache USING GIN (categories);

-- Verify seed data
DO $$
DECLARE
  tool_count INT;
BEGIN
  SELECT COUNT(*) INTO tool_count FROM tool_classification_cache;
  IF tool_count < 50 THEN
    RAISE NOTICE 'Warning: Only % tools classified. Expected at least 50.', tool_count;
  END IF;
END $$;
